function validate([n, bad]) {
  if (!Number.isInteger(n) || !Number.isInteger(bad)) return 'n and bad must be whole numbers.';
  if (n < 1 || n > 2147483647) return 'n is between 1 and 2^31 - 1.';
  if (bad < 1 || bad > n) return 'bad is between 1 and n.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [n, bad] = input;
  const limit = 64;
  let calls = 0;
  // LeetCode exposes the version check as a global API; the hidden answer stays inside it.
  globalThis.isBadVersion = version => {
    calls++;
    if (calls > limit) throw new Error('isBadVersion was called more than 64 times; search with far fewer calls.');
    return version >= bad;
  };
  return solve(n);
}

