function firstBadVersion(n) {
  let low = 1;
  let high = n;

  while (low < high) {
    const mid = low + Math.floor((high - low) / 2);
    if (isBadVersion(mid)) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return low;
}

